{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "code",
      "type": "string",
      "description": "The code string to display.",
      "required": true
    },
    {
      "name": "language",
      "type": "string | CodeLanguage",
      "description": "Language for syntax highlighting. A string selects a built-in: ts, js, tsx, jsx, json, html, xml, svg, css, scss, less, python, bash/sh/zsh/shell, php, hack, yaml, markdown, c, cpp (c++, cc, cxx, hpp, hh), sql, rust, kotlin, swift, go. Any other language is a value you import on its own and pass here: graphql, java, thrift, objectiveC, toml, powershell, ruby, lua, dockerfile from @astryxdesign/core/CodeBlock/languages/<path> (e.g. languages/graphql, languages/objective-c), or your own made with createCodeLanguage({name, identifiers, tokenize}). A value labels with its name and reflects its first identifier as data-language. Use \"plaintext\" to disable.",
      "default": "'plaintext'"
    },
    {
      "name": "title",
      "type": "string",
      "description": "Filename or label shown in the header bar."
    },
    {
      "name": "hasLanguageLabel",
      "type": "boolean",
      "description": "Show the language name in the header bar. Hidden when language is \"plaintext\".",
      "default": "true"
    },
    {
      "name": "hasLineNumbers",
      "type": "boolean",
      "description": "Show a line number gutter.",
      "default": "false"
    },
    {
      "name": "startLineNumber",
      "type": "number",
      "description": "First line number shown in the gutter. The gutter shows file coordinates (startLineNumber + index) so a code excerpt reads with its real line numbers. highlightLines uses the same file coordinates. Values below 1 clamp to 1.",
      "default": "1"
    },
    {
      "name": "highlightLines",
      "type": "number[]",
      "description": "1-indexed line numbers to highlight, in the same file coordinates as the gutter (see startLineNumber). Out-of-range entries render no highlight."
    },
    {
      "name": "isDiff",
      "type": "boolean",
      "default": "false",
      "description": "Render the code as a unified diff over `language`: lines starting with + are added, - removed, @@ is a hunk header (a `--- `/`+++ ` file-header pair directly before one is a header too), anything else is context. The language label reads `diff` or `<language> diff`. The glyph sits in its own column and the rest of each line keeps syntax highlighting; copy returns the exact source. Markdown ```diff and ```diff-<lang> fences set this."
    },
    {
      "name": "hasCopyButton",
      "type": "boolean",
      "description": "Show a copy-to-clipboard button.",
      "default": "true"
    },
    {
      "name": "onCopy",
      "type": "() => void",
      "description": "Callback after the code is copied."
    },
    {
      "name": "onCopyError",
      "type": "(error: unknown) => void",
      "description": "Called once with the rejection when the clipboard write fails. The copy button shows a cross and is named and announced as \"Failed to copy value to clipboard.\"; the error is not shown."
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Your own controls, shown just before Copy: in the header when the block has one, otherwise beside the code in the top inline-end corner, never over it. It never creates a header and never collapses the block. Ghost sm IconButtons match Copy’s size and variant.",
      "slotElements": [
        {
          "__element": "IconButton",
          "props": {
            "variant": "ghost",
            "size": "sm",
            "label": "Run in terminal"
          }
        }
      ]
    },
    {
      "name": "isWrapped",
      "type": "boolean",
      "description": "Wrap long lines instead of enabling horizontal scroll.",
      "default": "false"
    },
    {
      "name": "maxHeight",
      "type": "number | string",
      "description": "Max height before the block scrolls vertically."
    },
    {
      "name": "size",
      "type": "'sm' | 'md'",
      "description": "Text size variant.",
      "default": "'md'"
    },
    {
      "name": "width",
      "type": "string",
      "description": "Width of the code block. Any CSS width value. 'fit-content' (default) shrinks to longest line. '100%' fills parent width.",
      "default": "'fit-content'"
    },
    {
      "name": "container",
      "type": "'card' | 'section'",
      "description": "Container presentation style. 'card' (default): border and radius with the muted syntax background for a standalone card look. 'section': no border or radius and a transparent background so the block blends into the card or panel it's embedded in.",
      "default": "'card'"
    },
    {
      "name": "tokenizer",
      "type": "(code: string, language: string) => Array<{type: string; start: number; end: number}>",
      "description": "Deprecated: pass language={createCodeLanguage({name, identifiers, tokenize})} with this same function instead. Still works exactly as released and wins over the language; astryx upgrade rewrites static uses."
    },
    {
      "name": "syntaxTheme",
      "type": "SyntaxThemeDefinition",
      "description": "Per-instance syntax theme override. Shorthand for wrapping the block in <SyntaxTheme theme={...}>. Accepts a preset from @astryxdesign/core/theme/syntax or a theme created with defineSyntaxTheme(). Defaults to the nearest SyntaxTheme ancestor or the theme-level syntax colors."
    },
    {
      "name": "highlightMode",
      "type": "'auto' | 'ranges' | 'spans'",
      "description": "Syntax highlighting rendering mode.",
      "default": "'auto'"
    },
    {
      "name": "isCollapsible",
      "type": "boolean",
      "description": "Allow collapsing the code body into just the header bar. Starts expanded; a visible header becomes clickable when the code exceeds collapsibleThreshold lines. Headerless blocks never collapse, and removing the header expands a previously collapsed block.",
      "default": "false"
    },
    {
      "name": "collapsibleThreshold",
      "type": "number",
      "description": "Minimum number of lines before the collapse toggle appears. Below this threshold the code block renders normally even when isCollapsible is true.",
      "default": "10"
    },
    {
      "name": "ref",
      "type": "React.Ref<HTMLPreElement>",
      "description": "Ref forwarded to the root code-block element."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization. Must be a stylex.create() value."
    },
    {
      "name": "className",
      "type": "string",
      "description": "CSS class name for the root element. Prefer xstyle for styling."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles. Prefer xstyle for StyleX-optimized styling."
    },
    {
      "name": "data-testid",
      "type": "string",
      "description": "Test selector for automated testing frameworks."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
